        action['tick'] = latest['tick']
        d = draw.take()
        if d and 'debug' not in action:
            action['debug'] = d
        try:
            _send(action)
        except (TypeError, ValueError):
            log(f'unserializable action at tick {latest['tick']}:\n{traceback.format_exc()}')
            _send({'tick': latest['tick'], **last})

